#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
vector<int>idx(n);for(int i=0;i<n;++i)idx[i]=i;
sort(idx.begin(),idx.end(),[&](int x,int y){return a[x]>a[y];});
vector<string>res(n);
for(int r=0;r<n;++r){
if(r==0)res[idx[r]]="Gold Medal";
else if(r==1)res[idx[r]]="Silver Medal";
else if(r==2)res[idx[r]]="Bronze Medal";
else res[idx[r]]=to_string(r+1);}
for(int i=0;i<n;++i){if(i)printf(" ");printf("%s",res[i].c_str());}
printf("\n");return 0;}

